SELECT *
FROM cus_customer_scope_slice
WHERE tenant_id = #{query.tenantId}
  AND status = 'ACTIVE'
  AND effective_from <= #{query.effectiveAt}
  AND (effective_to IS NULL OR effective_to > #{query.effectiveAt})
  AND (
    (subject_type = 'USER' AND subject_id = #{query.userId})

        OR (subject_type = 'ROLE' AND subject_id IN

            #{roleId}
        )

  )
  AND deleted = b'0'
ORDER BY id
